(function(){
  function iso(dt){ return dt.toISOString().replace(/\.\d{3}Z$/,''+'Z'); }
  // Contract artefact 5 assigns flow 5 as the rescheduler of THREE concerns, not
  // one: policy-void, renewal-generate and renewal-dispatch. Each target is
  // resolved DYNAMICALLY from the published workflow list by name, because
  // scheduleFlow's subject-existence check is commented out (schedule.go:110-112)
  // and a typo'd subject returns 200 and produces a live timer that fires into
  // nothing. Refusing to schedule beats booking a dead timer.
  var want = ['policy-void','renewal-generate','renewal-dispatch'];
  var subjects = {};
  var list = (flows || []);
  for (var i=0; i<list.length; i++) {
    var f = list[i];
    if (!f || !f.subject) continue;
    // A draft subject carries an extra ".draft." token and is REJECTED by
    // schedule-flow, so it must never be matched here.
    if (String(f.subject).indexOf('.draft.') >= 0) continue;
    for (var w=0; w<want.length; w++) { if (f.name === want[w] && !subjects[want[w]]) subjects[want[w]] = f.subject; }
  }
  var missing = [];
  for (var m=0; m<want.length; m++) { if (!subjects[want[m]]) missing.push(want[m]); }

  var days = (voidAfterDays === undefined || voidAfterDays === null) ? 61 : Number(voidAfterDays);
  if (!(days > 0)) days = 61;
  var now = new Date();
  var nowIso = iso(now);
  var due = new Date(now.getTime() + days*24*60*60*1000);

  // Artefact 5, "Past trigger_on": if a computed trigger_on is already in the
  // past, do NOT call schedule-flow — stamp the empty string and continue. A
  // policy inside its last 100 days produces a T-100 that has already gone.
  var exp = expirationDate ? new Date(expirationDate) : null;
  var hasExp = !!(exp && !isNaN(exp.getTime()));
  var onGen = hasExp ? new Date(exp.getTime() - 100*24*60*60*1000) : null;
  var onDisp = hasExp ? new Date(exp.getTime() - 90*24*60*60*1000) : null;
  var renewalInPast = !hasExp || onGen.getTime() <= now.getTime() || onDisp.getTime() <= now.getTime();

  return {
    found: missing.length === 0,
    missing: missing,
    subject: subjects['policy-void'] || '',
    subject_renewal_generate: subjects['renewal-generate'] || '',
    subject_renewal_dispatch: subjects['renewal-dispatch'] || '',
    void_due_date: iso(due),
    void_after_days: days,
    now: nowIso,
    expiration_date: hasExp ? iso(exp) : '',
    on_renewal_generate: renewalInPast ? '' : iso(onGen),
    on_renewal_dispatch: renewalInPast ? '' : iso(onDisp),
    renewal_timers_in_past: renewalInPast,
    // ASSERT-1c: every name is composed from the frozen registry, never from a
    // literal this flow invented.
    name: 'policy-void:' + policyId,
    name_renewal_generate: 'renewal-generate:' + policyId,
    name_renewal_dispatch: 'renewal-dispatch:' + policyId
  };
})();

(function(){
  // ASSERT-1b, applied to a reschedule exactly as flow 2 applies it to a bind:
  // the returned topics are distinct non-empty strings. Cheap, and it catches a
  // name or target-flow collision here rather than at the next void.
  function topicOf(resp){
    if (!resp || typeof resp !== 'object') return '';
    if (typeof resp.topic === 'string') return resp.topic;
    if (resp.data && typeof resp.data.topic === 'string') return resp.data.topic;
    if (resp.results && resp.results.length && resp.results[0].topic) return resp.results[0].topic;
    return '';
  }
  var t = {
    policy_void_timer_topic: topicOf(sVoid),
    renewal_generate_timer_topic: skipRenewal ? '' : topicOf(sGen),
    renewal_dispatch_timer_topic: skipRenewal ? '' : topicOf(sDisp)
  };
  var required = ['policy_void_timer_topic'];
  if (!skipRenewal) { required.push('renewal_generate_timer_topic'); required.push('renewal_dispatch_timer_topic'); }
  var live = [], uniq = {};
  for (var i=0;i<required.length;i++){
    var v = t[required[i]];
    // Artefact 5: fail the run. Do not compensate, do not retry in-node, do not
    // compute the topic locally as a substitute. A policy that does not carry
    // its topics can never have its timers cancelled.
    if (!v) throw new Error('policy-reinstate ASSERT-1b FAILED: ' + required[i] + ' is empty — a timer was rescheduled that nothing can ever cancel');
    if (uniq[v]) throw new Error('policy-reinstate ASSERT-1b FAILED: two concerns returned the same topic ' + v);
    uniq[v] = 1; live.push(v);
  }
  t.distinct_topics = live.length;
  t.renewal_timers_skipped = !!skipRenewal;
  return t;
})();

